mapper.select:
SELECT ATT_SO.SUBSIDIARY_CODE ,TO_CHAR(ATT_SO.TIME_AND_ATTENDANCE_DATE, 'DD/MM/YYYY') AS TIME_AND_ATTENDANCE_DATE ,ATT_SO.EMPLOYEE_NO ,EM.FULL_NAME_LOCAL AS employee_Name ,EM.ORG_NAME_LOCAL AS organization_Name ,EM.organization_ID AS organization_ID ,tar.shift_type_code AS SHIFT_TYPE_CODE ,(SELECT lgvhr_common_pkg.decode_lookup('LGVHR_SHIFT_TYPE_CODE', tar.shift_type_code, NULL, 'en') AS FROM dual) AS SHIFT_TYPE_NAME ,lgvatt_common_pkg.get_att_code_info(tar.subsidiary_code, tar.time_and_attendance_code, 'NAME') AS attendance_name ,(SELECT lgvatt_common_pkg.get_holiday_flag(tar.subsidiary_code, tar.shift_type_code, tar.time_and_attendance_date) FROM DUAL) AS holiday_flag ,ATT_SO.SPECIAL_WORK_TYPE_CODE ,ATT_SO.TIME_AND_ATTENDANCE_YYYYMM ,ATT_SO.WORK_START_TIME ,ATT_SO.WORK_END_TIME ,ATT_SO.NIGHT_SHIFT_FLAG ,ATT_SO.OVERTIME_SUM_HOURS ,ATT_SO.WEEKDAY_OVERTIME_HOURS ,ATT_SO.HOLIDAY_OVERTIME_HOURS ,ATT_SO.PUBLIC_HOLIDAY_OVERTIME_HOURS ,ATT_SO.WEEKDAY_NIGHT_OVERTIME_HOURS ,ATT_SO.WEEKDAY_OT_AF_NIGHT_WORK_HOURS ,ATT_SO.HOLIDAY_NIGHT_OVERTIME_HOURS ,ATT_SO.PUBLIC_HOLIDAY_NIGHT_OT_HOURS ,ATT_SO.NORMAL_NIGHT_OVERTIME_HOURS ,ATT_SO.TIME_ATTEND_INPUT_REASON_DESC ,ATT_SO.TIME_ATTEND_DETAIL_CODE ,ATT_SO.CREATION_USER_ID ,ATT_SO.CREATION_DATE ,ATT_SO.LAST_UPDATE_USER_ID ,ATT_SO.LAST_UPDATE_DATE FROM TB_ATT_SPECIAL_OT_RESULT_N ATT_SO LEFT OUTER JOIN EMP_MASTER EM ON (ATT_SO.EMPLOYEE_NO = EM.EMPLOYEE_NUMBER) LEFT OUTER JOIN tb_att_result_n tar ON (tar.employee_no = ATT_SO.EMPLOYEE_NO AND TAR.time_and_attendance_date = ATT_SO.TIME_AND_ATTENDANCE_DATE) WHERE 1=1 AND ATT_SO.SUBSIDIARY_CODE = #{subsidiaryCode}
AND ATT_SO.REQUEST_NO = #{requestNo}
AND ATT_SO.approval_request_id = #{requestMasterId} ORDER BY ATT_SO.REQUEST_SEQ_NO ASC

mapper.update:
	 MERGE /* LGVATT20070.saveSpecialOt */ INTO TB_ATT_SPECIAL_OT_RESULT_N ATT_SO
     USING DUAL
             ON (     
                  	  ATT_SO.REQUEST_CODE = #{requestCode}
                  AND ATT_SO.APPROVAL_REQUEST_ID = #{approvalRequestId}
                  AND ATT_SO.EMPLOYEE_NO = #{employeeNo}
                  AND ATT_SO.TIME_AND_ATTENDANCE_DATE = TO_DATE(#{timeAndAttendanceDate}, 'DD/MM/YYYY')
                )
       WHEN MATCHED THEN
            UPDATE SET                         
                     ATT_SO.WEEKDAY_OVERTIME_HOURS         = #{weekdayOvertimeHours}
                    ,ATT_SO.HOLIDAY_OVERTIME_HOURS         = #{holidayOvertimeHours}
                    ,ATT_SO.PUBLIC_HOLIDAY_OVERTIME_HOURS  = #{publicHolidayOvertimeHours}
                    ,ATT_SO.WEEKDAY_NIGHT_OVERTIME_HOURS   = #{weekdayNightOvertimeHours}
                    ,ATT_SO.WEEKDAY_OT_AF_NIGHT_WORK_HOURS = #{weekdayOtAfNightWorkHours}
                    ,ATT_SO.HOLIDAY_NIGHT_OVERTIME_HOURS   = #{holidayNightOvertimeHours}
                    ,ATT_SO.PUBLIC_HOLIDAY_NIGHT_OT_HOURS  = #{publicHolidayNightOtHours}
                    ,CONFIRM_FLAG						   = 'Y'
                    ,PROGRESS_STATUS_CODE				   = (SELECT status_code FROM lgcom_approval_request_n WHERE request_master_id = ATT_SO.approval_request_id AND request_code = ATT_SO.request_code) 
                    ,LAST_UPDATE_USER_ID                   = #{sessionUserId}
                    ,LAST_UPDATE_DATE                      = SYSDATE
       WHEN NOT MATCHED THEN
            INSERT 
                   ( 
                    REQUEST_NO
                   ,REQUEST_SEQ_NO 
                   ,REQUEST_DATE
                   ,SUBSIDIARY_CODE
                   ,TIME_AND_ATTENDANCE_DATE
                   ,EMPLOYEE_NO
                   ,SPECIAL_WORK_TYPE_CODE
                   ,TIME_AND_ATTENDANCE_YYYYMM
                   ,WORK_START_TIME
                   ,WORK_END_TIME
                   ,EVENING_MEAL_FLAG
                   ,NIGHT_SHIFT_FLAG
                   ,OVERTIME_SUM_HOURS
                   ,WEEKDAY_OVERTIME_HOURS
                   ,HOLIDAY_OVERTIME_HOURS
                   ,PUBLIC_HOLIDAY_OVERTIME_HOURS
                   ,WEEKDAY_NIGHT_OVERTIME_HOURS
                   ,WEEKDAY_OT_AF_NIGHT_WORK_HOURS
                   ,HOLIDAY_NIGHT_OVERTIME_HOURS
                   ,PUBLIC_HOLIDAY_NIGHT_OT_HOURS
                   ,NORMAL_NIGHT_OVERTIME_HOURS
                   ,TIME_ATTEND_INPUT_REASON_DESC
                   ,TIME_ATTEND_DETAIL_CODE
                   ,APPROVAL_REQUEST_ID
                   ,REQUEST_CODE
                   ,PROGRESS_STATUS_CODE
                   ,CONFIRM_FLAG                   
                   ,CREATION_USER_ID
                   ,CREATION_DATE
                   ,LAST_UPDATE_USER_ID
                   ,LAST_UPDATE_DATE
                    )VALUES(
                    #{requestNo}
                   ,sq_tb_att_special_ot_id.NEXTVAL
                   ,SYSDATE
                   ,#{subsidiaryCode} 
                   ,TO_DATE(#{timeAndAttendanceDate}, 'DD/MM/YYYY')
                   ,#{employeeNo}
                   ,'SO'
                   ,TO_CHAR(TO_DATE(#{timeAndAttendanceDate}, 'DD/MM/YYYY'), 'YYYYMM')
                   ,#{workStartTime}
                   ,#{workEndTime}
                   ,'N'
                   ,#{nightShiftFlag}
                   ,#{overtimeSumHours}
                   ,#{weekdayOvertimeHours}
                   ,#{holidayOvertimeHours}
                   ,#{publicHolidayOvertimeHours}
                   ,#{weekdayNightOvertimeHours}
                   ,#{weekdayOtAfNightWorkHours}
                   ,#{holidayNightOvertimeHours}
                   ,#{publicHolidayNightOtHours}
                   ,0
                   ,#{timeAttendInputReasonDesc}
                   ,'NW'
                   ,#{approvalRequestId}
                   ,#{requestCode}
                   ,'20'
                   ,'N'                     
                   ,#{sessionUserId}
                   ,SYSDATE
                   ,#{sessionUserId}
                   ,SYSDATE
                       )

	UPDATE TB_ATT_SPECIAL_OT_RESULT_N ATT_SO
	   SET ATT_SO.PROGRESS_STATUS_CODE		= (SELECT status_code FROM lgcom_approval_request_n WHERE request_master_id = ATT_SO.approval_request_id AND request_code = ATT_SO.request_code) 
          ,ATT_SO.LAST_UPDATE_USER_ID      = #{sessionUserId}
          ,ATT_SO.LAST_UPDATE_DATE         = SYSDATE
	 WHERE ATT_SO.SUBSIDIARY_CODE 			= #{LGVHR_PROJECT_SESSION.subsidiaryCode} 
	   AND ATT_SO.REQUEST_CODE 			= #{requestCode}
       AND ATT_SO.APPROVAL_REQUEST_ID 		= #{approvalRequestId}

DELETE FROM TB_ATT_SPECIAL_OT_RESULT_N ATT_SO
 WHERE ATT_SO.SUBSIDIARY_CODE = #{subsidiaryCode} 
   AND ATT_SO.TIME_AND_ATTENDANCE_DATE = TO_DATE(#{timeAndAttendanceDate}, 'DD/MM/YYYY') 
   AND ATT_SO.EMPLOYEE_NO = #{employeeNo}

mapper.select:
SELECT
EM.FULL_NAME_LOCAL AS requestor_info ,(SELECT common_code_name FROM LGCOM_COMMON_CODE_MULTI_LANG_C WHERE code_type_code = 'LGCOM_APPROVAL_REQ_STATUS_CODE' AND language_code = NVL('en','en') AND common_code = ATT_SO.PROGRESS_STATUS_CODE) AS status_name ,TO_CHAR(ATT_SO.LAST_UPDATE_DATE, 'DD/MM/YYYY') AS request_date , ATT_SO.PROGRESS_STATUS_CODE as startus_code
FROM TB_ATT_SPECIAL_OT_RESULT_N ATT_SO LEFT OUTER JOIN EMP_MASTER EM ON (ATT_SO.EMPLOYEE_NO = EM.EMPLOYEE_NUMBER) LEFT OUTER JOIN tb_att_result_n tar ON (tar.employee_no = ATT_SO.EMPLOYEE_NO AND TAR.time_and_attendance_date = ATT_SO.TIME_AND_ATTENDANCE_DATE) WHERE 1=1 AND ATT_SO.TIME_AND_ATTENDANCE_DATE = TO_DATE(#{timeAndAttendanceDate}, 'DD/MM/YYYY') AND ATT_SO.EMPLOYEE_NO = #{employeeNo} AND ATT_SO.SUBSIDIARY_CODE = #{subsidiaryCode} AND ATT_SO.LAST_UPDATE_USER_ID = #{sessionUserId}
